function gunByName(name:string):GunDefinition|undefined{return (Object.values(GUNS) as GunDefinition[]).find(gun=>gun.name===name);}
function isGunId(value:string):value is GunId{return Object.prototype.hasOwnProperty.call(GUNS,value);}
function ammoForGun(save:PersistedSave,gun:GunDefinition){return save.gunAmmoState.find(state=>state.name===gun.name)??{name:gun.name,magazine:gun.magazineSize,reserve:gun.magazineSize*6};}
function setGunAmmo(save:PersistedSave,gun:GunDefinition,magazine:number,reserve:number):PersistedSave{return{...save,gunAmmoState:[...save.gunAmmoState.filter(state=>state.name!==gun.name),{name:gun.name,magazine:Math.max(0,Math.min(gun.magazineSize,Math.round(magazine))),reserve:Math.max(0,Math.min(5000,Math.round(reserve)))}].slice(-4)};}
function addGunToSave(save:PersistedSave,gun:GunDefinition):PersistedSave{const hasAmmo=save.gunAmmoState.some(state=>state.name===gun.name);return{...save,items:[...new Set([...save.items,gun.name])].slice(-60),gunAmmoState:hasAmmo?save.gunAmmoState:[...save.gunAmmoState,{name:gun.name,magazine:gun.magazineSize,reserve:gun.magazineSize*6}].slice(-4)};}
function ownsOrHasPendingGun(save:PersistedSave,gunId:GunId):boolean{const gun=GUNS[gunId];return save.weaponName===gun.name||save.items.includes(gun.name)||save.storedItems.includes(gun.name)||save.rareLootDrops.some(drop=>drop.itemId===`gun:${gunId}`);}
function createGunDrop(save:PersistedSave,gunId:GunId,sourceId:number,x:number,y:number):{pickup:Pickup;drop:{id:number;itemId:string;x:number;y:number}}|null{if(ownsOrHasPendingGun(save,gunId))return null;const id=1_820_000_000+(Math.abs(sourceId)%100_000),gun=GUNS[gunId],drop={id,itemId:`gun:${gunId}`,x,y};return{drop,pickup:{id,x,y,kind:"gun",value:0,taken:false,label:gun.name,gunId}};}

