  if(enemy.zone===12){ctx.fillStyle="#ddf8ff";for(const [x,y,a] of [[-17,-22,-.2],[6,-27,.2],[-25,7,-.4]] as const){ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.beginPath();ctx.moveTo(0,-10);ctx.lineTo(5,4);ctx.lineTo(-4,5);ctx.closePath();ctx.fill();ctx.restore();}}
